import {showElephantSteps} from './resolution-pages.js';
import {IDS,PRESIDENCIES,REGIONS,ALLIANCES,legalTargets,deploymentBlockReason,deploymentStrength,deploymentCheck,resolveDeployment} from './model.js';
export function openDeployment({state,showDialog,apply,esc,targetRegion=null,army=null}){
 const $=id=>document.getElementById(id);
 if(army!==null&&!PRESIDENCIES.includes(army))throw Error('Choose a valid originating Army.');
 const fixedArmy=army;
 // Old unconfirmed deployment drafts no longer block or survive reopening.
 try{localStorage.removeItem('jc-deploy-draft-v2');}catch{}
 const armyReason=army=>targetRegion?deploymentBlockReason(state,army,targetRegion):legalTargets(state,army).length?'':'No legal target is available to this army this turn.';
 let reviewReady=false,reviewCursor=0;
 let step=fixedArmy?1:0,d={army:fixedArmy||PRESIDENCIES.find(a=>!armyReason(a))||'bombay',target:targetRegion||'',officers:0,regiments:0,alliances:[],outcome:'',losses:0};
 const options=(ids,value)=>ids.map(id=>`<option value="${id}" ${id===value?'selected':''}>${REGIONS[id].name}</option>`).join('');
 function draw(){
  if(step===5&&!reviewReady){const result=resolveDeployment(state,d);showElephantSteps({instructions:result.instructions,elephantMoves:result.elephantMoves||[],showDialog,esc,onDone:cursor=>{reviewCursor=cursor;reviewReady=true;draw();}});return;}
  let body='',title=['Choose an army','Choose a legal target','Commit available forces','Report the check','Check officer losses','Review deployment'][step];
  if(step===0)body=`${targetRegion?`<p class="notice">Target: <b>${esc(REGIONS[targetRegion].name)}</b></p>`:''}<label>Army<select id="army">${PRESIDENCIES.map(a=>`<option value="${a}" ${a===d.army?'selected':''} ${armyReason(a)?'disabled':''}>Army of ${REGIONS[a].name}</option>`).join('')}</select></label><div class="army-reasons">${PRESIDENCIES.map(a=>`<p><b>Army of ${REGIONS[a].name}:</b> ${esc(armyReason(a)||'Available for this target. Check unexhausted forces on the physical board.')}</p>`).join('')}</div><p>Use the physical Army box to check available pieces. Buy any local alliances through the President before deploying.</p>`;
  if(step===1){const targets=legalTargets(state,d.army);if(!targets.includes(d.target))d.target=targets[0]||'';body=`<label>Target<select id="target">${options(targets,d.target)}</select></label><p>${targets.length?'Only legal targets are shown. Your home region can be targeted directly; expansion requires a border with Company territory assigned to this Presidency. Other Presidents’ home regions are excluded. Company regions must have unrest or a closed order.':'No legal targets. This army may have suffered a catastrophic failure this turn.'}</p><details><summary>Why other regions are unavailable</summary>${IDS.filter(id=>!targets.includes(id)).map(id=>`<p><b>${REGIONS[id].name}:</b> ${esc(deploymentBlockReason(state,d.army,id))}</p>`).join('')}</details>`;}
  if(step===2)body=`<div class="fields"><label>Regiments<input id="regiments" type="number" min="0" max="100" value="${d.regiments}"></label><label>Officers<input id="officers" type="number" min="0" max="100" value="${d.officers}"></label></div><h4>Local alliances · Army of ${REGIONS[d.army].name}</h4>${ALLIANCES.filter(a=>a.army===d.army).map(a=>`<label class="check-label"><input type="checkbox" data-alliance="${a.id}" ${d.alliances.includes(a.id)?'checked':''}>${a.name} · strength ${a.strength} · purchase £${a.cost}</label>`).join('')}<p>Commit only purchased, unexhausted pieces in this Army. Alliances cannot split their strength. The app records participation, not a persistent roster.</p><div class="notice"><b>${state.regions[d.target].control!=='company'&&state.regions[d.target].lootAvailable?'£'+REGIONS[d.target].lootBonus+' regional loot bonus available':'Regional loot bonus already claimed'}</b><p class="small-note">${state.regions[d.target].control!=='company'&&state.regions[d.target].lootAvailable?'Included automatically on success.':'No regional bonus will be added.'} Normal loot also includes £4 per target tower level, with the rules’ minimum payout.</p></div>`;
  if(step===3){const c=deploymentCheck(state,d);body=`<div class="notice"><b>Roll ${c.dice} dice</b> · ${c.strength} committed strength − ${c.defense} regional / empire defence.</div><p>Exhaust the committed pieces. Resolve any permitted rerolls on the table, then report the lowest die.</p><label>Final outcome<select id="outcome"><option value="">Choose outcome…</option>${[['success','1–2 · Success'],['failure','3–4 · Failure'],['catastrophe','5–6 · Catastrophic failure']].map(([v,l])=>`<option value="${v}" ${d.outcome===v?'selected':''}>${l}</option>`).join('')}</select></label><p>On catastrophe, first return half the Commander’s trophies (rounded up) and remove the Commander. The office cannot act again this turn.</p>`;}
  if(step===4)body=`<p>For <b>every outcome</b>, each player rolls one die per officer they exhausted in this action. Each 6 removes one of their officers to supply. Never check regiments.</p><label>Officers lost out of ${d.officers}<input id="losses" type="number" min="0" max="${d.officers}" value="${d.losses}"></label><p class="small-note">Report the total after all players finish. This is separate from removing the Commander after catastrophe.</p>`;
  if(step===5){const r=resolveDeployment(state,d);body=`<h4>${esc(r.title)}</h4><p>Apply the following on the physical board. Confirming records this deployment and updates the app together.</p><ol>${r.instructions.slice(reviewCursor).map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="small-note">No cash, trophy totals or player identities are tracked. Closing without confirming leaves the app unchanged; reverse any unconfirmed physical changes yourself. Undo reverses a confirmed action.</p>`;}
  if(step>=1&&step<=3)body='<div id="strength-summary"></div>'+body;
  showDialog(`Deploy · ${title}`,`${fixedArmy?`<p class="notice"><b>${REGIONS[fixedArmy].name} Army</b> · Origin fixed for this deployment.</p>`:''}<p class="eyebrow">STEP ${fixedArmy?step:targetRegion?(step||1):step+1} OF ${fixedArmy||targetRegion?5:6}</p>${fixedArmy&&step===1?'<p>Use the physical Army box to check available pieces. Buy any local alliances through the President before deploying.</p>':''}${body}`,`<button id="cancel-deploy">Cancel</button>${step>(fixedArmy?1:0)?'<button id="back-deploy">Back</button>':''}<button id="next-deploy" class="primary" ${(step===0&&armyReason(d.army))||(step===1&&!legalTargets(state,d.army).length)?'disabled':''}>${step===5?'Confirm & apply':'Continue'}</button>`);
  const capture=()=>{if(step===0){if(d.army!==$('army').value){d.target=targetRegion||'';d.alliances=[];}d.army=$('army').value;$('next-deploy').disabled=!!armyReason(d.army);}if(step===1)d.target=$('target').value;if(step===2){d.regiments=Number($('regiments').value);d.officers=Number($('officers').value);d.alliances=[...document.querySelectorAll('[data-alliance]:checked')].map(e=>e.dataset.alliance);}if(step===3)d.outcome=$('outcome').value;if(step===4)d.losses=Number($('losses').value);updateStrength();};
  function updateStrength(){
   const panel=$('strength-summary');if(!panel)return;
   if(!d.target){panel.innerHTML='';return;}
   const c=deploymentStrength(state,d),r=state.regions[d.target];
   panel.innerHTML=`<section class="strength-card"><p class="eyebrow">${esc(REGIONS[d.target].name)} · ${r.control==='company'?'COMPANY REGION':c.defenders.length>1?'EMPIRE DEFENCE':'REGIONAL DEFENCE'}</p><div class="strength-columns"><div><h4>Defending strength</h4>${c.defenders.map(v=>`<div class="strength-row"><span>${esc(REGIONS[v.id].name)}${v.id===d.target?' (target)':''}</span><b>${v.strength}</b></div>`).join('')}<div class="strength-row strength-total"><span>Total defence</span><b>${c.defense}</b></div></div>${step>1?`<div><h4>Committed strength</h4><div class="strength-row"><span>Regiments</span><b>${d.regiments}</b></div><div class="strength-row"><span>Officers</span><b>${d.officers}</b></div>${c.allies.map(a=>`<div class="strength-row"><span>${esc(a.name)}</span><b>${a.strength}</b></div>`).join('')}<div class="strength-row strength-total"><span>Total committed</span><b>${c.strength}</b></div></div>`:''}</div>${step>1?`<div class="dice-total" role="status" aria-live="polite"><strong>${c.strength} − ${c.defense} = ${c.dice} dice</strong><span>${c.dice>0?'Ready to roll after committing these forces.':`No roll available. Add ${1-c.dice} more strength to roll at least one die.`}</span></div>`:''}${r.control==='company'?'<p class="small-note">Company-controlled regions have zero defending strength.</p>':c.defenders.length>1?'<p class="small-note">All regions in the defending empire contribute, including the capital and every subject.</p>':''}</section>`;
  }
  updateStrength();
  $('dialog-content').onchange=capture;
  $('cancel-deploy').onclick=()=>{$('dialog-content').onchange=null;$('dialog').close();};
  if(step>(fixedArmy?1:0))$('back-deploy').onclick=()=>{capture();reviewReady=false;reviewCursor=0;step=targetRegion&&step===2?0:step-1;draw();};
  $('next-deploy').onclick=()=>{try{capture();if(step===0&&armyReason(d.army))throw Error(armyReason(d.army));if(step===1&&!legalTargets(state,d.army).includes(d.target))throw Error('No legal target selected.');if(step===2)deploymentCheck(state,d);if(step===3&&!d.outcome)throw Error('Choose the final outcome.');if(step===4)resolveDeployment(state,d);if(step===5){const result=resolveDeployment(state,d);apply(result);$('dialog-content').onchange=null;$('dialog').close();return;}step=targetRegion&&step===0?2:step+1;draw();}catch(e){$('form-error').textContent=e.message;}};
 }
 draw();
}
